  james: {lugar:"Cambridge, Massachusetts (Harvard)", lat:42.37, lon:-71.12, nace:1842, muere:1910, otros:[{lugar:"Nueva York", lat:40.71, lon:-74.01, nota:"Nació allí."},{lugar:"Chocorua (New Hampshire)", lat:43.88, lon:-71.23, nota:"Su casa de verano, donde murió."}]},
