  salazarbondy: {lugar:"Lima", lat:-12.05, lon:-77.04, nace:1925, muere:1974, otros:[{lugar:"Ciudad de México", lat:19.43, lon:-99.13, nota:"Estudió allí con José Gaos a fines de los años cuarenta."}]},
